package main

import (
	"fmt"
	"sync"
)

func main() {
	input := []int{2, 3, 4}
	result := make([]int, len(input))
	var wg sync.WaitGroup

	for i, value := range input {
		i, value := i, value
		wg.Go(func() {
			result[i] = value * value
		})
	}

	wg.Wait()
	fmt.Println(result)
}
```
Each worker owns one slice element. Wait orders the completed writes before the final read; it is not being used as a lock.

```go
package main

import (
	"fmt"
	"sync"
)

func doubleAll(values []int) []int {
	result := make([]int, len(values))
	var wg sync.WaitGroup
	wg.Add(len(values))

	for i, value := range values {
		i, value := i, value
		go func() {
			defer wg.Done()
			result[i] = value * 2
		}()
	}
	wg.Wait()
	return result
}

func main() {
	fmt.Println(doubleAll([]int{1, 2, 3}))
}
```
The whole positive delta is registered before any worker starts, and every worker owns one result index and one deferred Done.

```go
package main

import (
	"fmt"
	"sort"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	var mu sync.Mutex
	values := make([]int, 0, 2)

	wg.Go(func() {
		for _, value := range []int{4, 2} {
			value := value
			wg.Go(func() {
				mu.Lock()
				values = append(values, value)
				mu.Unlock()
			})
		}
	})

	wg.Wait()
	sort.Ints(values)
	fmt.Println(values)
}
```
The outer task registers children while the group is non-empty. The mutex, not the WaitGroup, protects append.
